mapper.select:
WITH RECURSIVE subtree AS (
    SELECT "フォルダID", 0 AS height FROM public."DOC_フォルダ情報"
     WHERE "家族学生ID" = #{familyStudentId} AND "フォルダID" = #{folderId}
    UNION ALL
    SELECT child."フォルダID", parent.height + 1
      FROM public."DOC_フォルダ情報" child
      JOIN subtree parent ON child."親フォルダID" = parent."フォルダID"
     WHERE child."家族学生ID" = #{familyStudentId}
)
SELECT COALESCE(MAX(height), 0) FROM subtree

WITH RECURSIVE subtree AS (
    SELECT "フォルダID" FROM public."DOC_フォルダ情報"
     WHERE "家族学生ID"=#{familyStudentId} AND "フォルダID"=#{rootFolderId}
    UNION ALL
    SELECT child."フォルダID" FROM public."DOC_フォルダ情報" child
      JOIN subtree parent ON child."親フォルダID"=parent."フォルダID"
     WHERE child."家族学生ID"=#{familyStudentId}
)
SELECT COUNT(*) FROM subtree WHERE "フォルダID"=#{candidateFolderId}

SELECT * FROM public."DOC_資料情報" WHERE "家族学生ID"=#{familyStudentId}
AND "フォルダID"=#{folderId}

    AND ("資料番号" ILIKE CONCAT('%',#{keyword},'%') OR COALESCE("コメント",'') ILIKE CONCAT('%',#{keyword},'%'))

ORDER BY "更新日時" DESC NULLS LAST, "資料番号" DESC

mapper.delete:
DELETE FROM public."DOC_資料詳細情報" D USING public."DOC_資料情報" M
 WHERE M."資料番号"=D."資料番号" AND M."家族学生ID"=#{familyStudentId}
   AND D."資料番号"=#{documentNo} AND D."枝番号"=#{branchNo}

DELETE FROM public."DOC_資料詳細情報" D USING public."DOC_資料情報" M
 WHERE M."資料番号"=D."資料番号" AND M."家族学生ID"=#{familyStudentId}
   AND D."資料番号"=#{documentNo}
